import { Building2 } from "lucide-react";
import type { ReactNode } from "react";

import { cn } from "@/lib/cn";

import { FrameImage, FrameMark } from "./ImageFrame";

// See web/registry/rules/components.md, OrganizationLogo.

export type OrganizationLogoShape = "profile";

const frames: Record<OrganizationLogoShape, string> = {
  profile: "aspect-square w-full rounded-md",
};

export interface OrganizationLogoProps {
  /** The logo's URL; without one, or when it fails to load, the placeholder shows. */
  src?: string;
  /** The image's alternative text, such as "Logo of {name}". */
  alt: string;
  shape: OrganizationLogoShape;
  /** Makes the placeholder a button with this name, such as "Add logo". */
  addLabel?: string;
  onAdd?: () => void;
  /** Marks drawn over the frame, placed with OrganizationLogoMark. */
  children?: ReactNode;
}

export function OrganizationLogo({
  src,
  alt,
  shape,
  addLabel,
  onAdd,
  children,
}: OrganizationLogoProps) {
  return (
    <div
      data-slot="organization-logo"
      data-shape={shape}
      className={cn(
        "relative shrink-0 overflow-hidden border border-border bg-muted",
        frames[shape],
      )}
    >
      <FrameImage
        src={src}
        alt={alt}
        // A cropped wordmark cannot be read, so the logo is drawn whole.
        imageClassName="object-contain"
        icon={<Building2 aria-hidden="true" className="size-1/3 text-muted-foreground" />}
        addLabel={addLabel}
        onAdd={onAdd}
      />
      {children}
    </div>
  );
}

/** A control or mark in a corner of the logo, held as a face's marks are. */
export const OrganizationLogoMark = FrameMark;

import { type ReactNode, useState } from "react";

import { cn } from "@/lib/cn";

// The image-or-placeholder body and the corner marks PersonFace and OrganizationLogo share.

export interface FrameImageProps {
  /** The image's URL; without one, or when it fails to load, the placeholder shows. */
  src?: string;
  alt: string;
  /** How the image fills the frame, such as `object-cover` or `object-contain`. */
  imageClassName: string;
  /** The placeholder's icon. */
  icon: ReactNode;
  /** Makes the placeholder a button with this name. */
  addLabel?: string;
  onAdd?: () => void;
}

export function FrameImage({
  src,
  alt,
  imageClassName,
  icon,
  addLabel,
  onAdd,
}: FrameImageProps) {
  // Remember which URL failed so that a new revision is tried again.
  const [failed, setFailed] = useState<string | null>(null);
  const shown = src !== undefined && failed !== src ? src : undefined;
  if (shown !== undefined) {
    return (
      <img
        src={shown}
        alt={alt}
        loading="lazy"
        decoding="async"
        onError={() => setFailed(shown)}
        className={cn("size-full", imageClassName)}
      />
    );
  }
  if (onAdd !== undefined) {
    return (
      <button
        type="button"
        aria-label={addLabel}
        onClick={onAdd}
        className="flex size-full items-center justify-center hover:bg-accent"
      >
        {icon}
      </button>
    );
  }
  return <span className="flex size-full items-center justify-center">{icon}</span>;
}

/** A control or mark in a corner of a card or profile frame. */
export function FrameMark({
  corner,
  children,
}: {
  corner: "top-end" | "bottom-end";
  children: ReactNode;
}) {
  return (
    <div
      data-slot="person-face-mark"
      className={cn(
        "absolute right-1.5 z-20 flex [&_svg]:drop-shadow-mark",
        corner === "top-end" ? "top-1.5" : "bottom-1.5",
      )}
    >
      {children}
    </div>
  );
}
